import fs from "node:fs"
import path from "node:path"
import type { QuartzComponent, QuartzComponentConstructor } from "../quartz/components/types"
import type { QuartzEmitterPlugin } from "../quartz/plugins/types"
import { FilePath, FullSlug, joinSegments, resolveRelative } from "../quartz/util/path"
import { languageOf } from "./bilingual"
import { cardKind, cardPath } from "./cards"
import { coverOf } from "./cover"

// Generated by brand/build.sh; see brand/README.md.
const BRAND = path.join("brand", "out")

// Output path → file in brand/out. Quartz's own icon.png and og-image.png are kept out of
// the core Static emitter by ignorePatterns, so these are the only ones on the site.
const FILES: Record<string, string> = {
  "favicon.ico": "favicon.ico",
  // Head.tsx links this without sizes, so browsers fetch it as one more favicon: the 48 px one.
  "static/icon.png": "favicon-48.png",
  "static/logo-88.png": "logo-88.png",
  "static/favicon-16.png": "favicon-16.png",
  "static/favicon-32.png": "favicon-32.png",
  "static/favicon-48.png": "favicon-48.png",
  "static/apple-touch-icon.png": "apple-touch-icon.png",
  "static/caveat.woff2": "caveat.woff2",
  "static/neucha.woff2": "neucha.woff2",
  "static/og-image.png": "og-image-ru.png",
  "static/og-image-ru.png": "og-image-ru.png",
  "static/og-image-en.png": "og-image-en.png",
}

// Named so that Head.tsx leaves the og:image tags to this plugin: each language gets its own card.
export const GardenBrand: QuartzEmitterPlugin = () => ({
  name: "CustomOgImages",
  async *emit(ctx) {
    for (const [dest, src] of Object.entries(FILES)) {
      const out = joinSegments(ctx.argv.output, dest) as FilePath
      await fs.promises.mkdir(path.dirname(out), { recursive: true })
      await fs.promises.copyFile(path.join(BRAND, src), out)
      yield out
    }
  },
  async *partialEmit() {},
  externalResources: (ctx) => {
    const base = `https://${ctx.cfg.configuration.baseUrl}`
    return {
      additionalHead: [
        // The 16 px icon is a simplified drawing, so browsers should not downscale the large one.
        <link rel="icon" type="image/png" sizes="16x16" href="/static/favicon-16.png" />,
        <link rel="icon" type="image/png" sizes="32x32" href="/static/favicon-32.png" />,
        <link rel="icon" type="image/png" sizes="48x48" href="/static/favicon-48.png" />,
        <link rel="apple-touch-icon" href="/static/apple-touch-icon.png" />,
        (pageData) => {
          // A page's own card first; then a text's cover, whose size is unknown here; then the
          // language card.
          const cover = coverOf(pageData)
          if (cover && !cardKind(pageData)) {
            const image = `${base}/${encodeURI(cover)}`
            return (
              <>
                <meta property="og:image" content={image} />
                <meta property="og:image:url" content={image} />
                <meta name="twitter:image" content={image} />
              </>
            )
          }
          const own = cardKind(pageData)
          const image = own
            ? `${base}/${encodeURI(cardPath(pageData.slug!))}`
            : `${base}/static/og-image-${languageOf(pageData.slug) ?? "ru"}.png`
          return (
            <>
              <meta property="og:image" content={image} />
              <meta property="og:image:url" content={image} />
              <meta property="og:image:type" content={own ? "image/jpeg" : "image/png"} />
              <meta property="og:image:width" content="1200" />
              <meta property="og:image:height" content="630" />
              <meta name="twitter:image" content={image} />
            </>
          )
        },
      ],
    }
  },
})

// The valve at the top left leads to the home page of the page's language; on the home page it is just the mark.
export const HomeLogo = (() => {
  const Logo: QuartzComponent = ({ fileData }) => {
    const slug = fileData.slug!
    const lang = languageOf(slug)
    const home = (lang ? `${lang}/index` : "index") as FullSlug
    const image = <img src="/static/logo-88.png" alt="" width="44" height="44" />
    if (slug === home) return <span class="home-logo">{image}</span>
    return (
      <a
        class="home-logo"
        href={resolveRelative(slug, home)}
        aria-label={lang === "en" ? "Home" : "На главную"}
      >
        {image}
      </a>
    )
  }
  Logo.css = `
.page-header header > .home-logo {
  order: -1;
  margin-right: auto;
  display: flex;
}
.home-logo img {
  margin: 0;
  border-radius: 0;
}
`
  return Logo
}) satisfies QuartzComponentConstructor
